from flask import Flask, request, jsonify
import base64, hmac, io, json, os
from PIL import Image, ImageDraw, ImageFont
import qrcode

app = Flask(__name__)

# Delt hemmelighet mellom Cloudflare-workeren og denne tjenesten.
# Endepunktene under lager bilder og PDF-er og er ellers helt apne, slik at
# hvem som helst kan kalle dem og bruke opp CPU-kvoten pa gratis-planen.
RENDER_API_SECRET = os.environ.get("RENDER_API_SECRET", "")


def krev_hemmelighet():
    """Returnerer et feilsvar hvis kallet mangler riktig hemmelighet, ellers None.

    Er RENDER_API_SECRET ikke satt, slippes kallet gjennom som for. Det gjor at
    tjenesten kan deployes for variabelen er lagt inn bade her og i workeren,
    uten nedetid. Sett den begge steder for a skru pa sperren.
    """
    if not RENDER_API_SECRET:
        return None
    oppgitt = request.headers.get("X-NBU-Secret", "")
    if not hmac.compare_digest(oppgitt, RENDER_API_SECRET):
        return jsonify({"ok": False, "feil": "Ikke tilgang."}), 403
    return None


SIDE1_B64 = ""
SIDE2_B64 = ""

def get_font(size):
    try:
        return ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", size)
    except:
        return ImageFont.load_default()

def get_font_regular(size):
    try:
        return ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", size)
    except:
        return ImageFont.load_default()

@app.route("/helse", methods=["GET"])
def helse():
    return jsonify({"ok": True})

# ═══ FRIVILLIG-KONTRAKT OG HENDELSESRAPPORT (PDF) ═══

PAGE_W, PAGE_H = 1240, 1754  # ca. A4 ved 150 dpi
MARGIN = 90
DGREEN = (74, 93, 36)
GREEN = (181, 200, 0)
INK = (40, 40, 35)
GREY = (110, 110, 105)

def wrap_text(draw, text, font, max_width):
    lines = []
    for paragraph in text.split("\n"):
        if not paragraph.strip():
            lines.append("")
            continue
        words = paragraph.split(" ")
        cur = ""
        for w in words:
            trial = (cur + " " + w).strip()
            bbox = draw.textbbox((0, 0), trial, font=font)
            if bbox[2] - bbox[0] > max_width and cur:
                lines.append(cur)
                cur = w
            else:
                cur = trial
        lines.append(cur)
    return lines

def new_page():
    img = Image.new("RGB", (PAGE_W, PAGE_H), (255, 255, 255))
    draw = ImageDraw.Draw(img)
    draw.rectangle([0, 0, PAGE_W, 14], fill=DGREEN)
    return img, draw

def draw_footer(draw, page_num, total, label):
    draw.text((MARGIN, PAGE_H - 60), label, font=get_font_regular(18), fill=GREY)
    txt = f"Side {page_num} av {total}"
    f = get_font_regular(18)
    bbox = draw.textbbox((0, 0), txt, font=f)
    draw.text((PAGE_W - MARGIN - (bbox[2] - bbox[0]), PAGE_H - 60), txt, font=f, fill=GREY)

@app.route("/frivillig-kontrakt", methods=["POST"])
def lag_kontrakt():
    avvist = krev_hemmelighet()
    if avvist:
        return avvist
    data = request.json
    navn = data.get("navn", "")
    alder = str(data.get("alder", ""))
    telefon = data.get("telefon", "")
    epost = data.get("epost", "")
    rolle = data.get("rolle", "")
    dato = data.get("dato", "")
    kontrakt_tekst = data.get("kontraktTekst", "")
    signatur_b64 = data.get("signaturB64", "")

    title_font = get_font(46)
    h2_font = get_font(26)
    label_font = get_font_regular(20)
    value_font = get_font(22)
    body_font = get_font_regular(21)

    pages = []
    img, draw = new_page()
    y = 70
    draw.text((MARGIN, y), "Norsjø Bygdeungdomslag", font=get_font(24), fill=GREY)
    y += 50
    draw.text((MARGIN, y), "Frivilligavtale", font=title_font, fill=DGREEN)
    y += 80

    felt = [("Navn", navn), ("Alder", alder + " år"), ("Telefon", telefon),
            ("E-post", epost), ("Rolle", rolle), ("Dato signert", dato)]
    col_w = (PAGE_W - 2 * MARGIN) // 2
    for i, (label, verdi) in enumerate(felt):
        col = i % 2
        row = i // 2
        x = MARGIN + col * col_w
        yy = y + row * 62
        draw.text((x, yy), label.upper(), font=label_font, fill=GREY)
        draw.text((x, yy + 24), str(verdi), font=value_font, fill=INK)
    y += (len(felt) + 1) // 2 * 62 + 30
    draw.line([(MARGIN, y), (PAGE_W - MARGIN, y)], fill=(220, 218, 205), width=2)
    y += 40

    draw.text((MARGIN, y), "Vilkår for frivillig arbeid", font=h2_font, fill=DGREEN)
    y += 46

    lines = wrap_text(draw, kontrakt_tekst, body_font, PAGE_W - 2 * MARGIN)
    max_y = PAGE_H - 260
    for line in lines:
        if y > max_y:
            pages.append(img)
            img, draw = new_page()
            y = 80
        draw.text((MARGIN, y), line, font=body_font, fill=INK)
        y += 32

    # Signatur nederst på siste side (ny side hvis ikke nok plass)
    if y > PAGE_H - 320:
        pages.append(img)
        img, draw = new_page()
        y = 80
    y = max(y + 40, PAGE_H - 300)
    draw.line([(MARGIN, y), (PAGE_W - MARGIN, y)], fill=(220, 218, 205), width=2)
    y += 30
    draw.text((MARGIN, y), "Elektronisk signatur", font=label_font, fill=GREY)
    y += 30
    if signatur_b64:
        try:
            sig_bytes = base64.b64decode(signatur_b64.split(",")[-1])
            sig_img = Image.open(io.BytesIO(sig_bytes)).convert("RGBA")
            sig_w = 360
            ratio = sig_w / sig_img.width
            sig_img = sig_img.resize((sig_w, int(sig_img.height * ratio)))
            bg = Image.new("RGBA", sig_img.size, (255, 255, 255, 255))
            bg.paste(sig_img, (0, 0), sig_img)
            img.paste(bg.convert("RGB"), (MARGIN, y))
            y += bg.height + 10
        except Exception:
            pass
    draw.text((MARGIN, y), f"{navn} – signert {dato}", font=value_font, fill=INK)
    pages.append(img)

    total = len(pages)
    for i, p in enumerate(pages):
        d = ImageDraw.Draw(p)
        draw_footer(d, i + 1, total, "Norsjø Bygdeungdomslag – Frivilligavtale")

    buf = io.BytesIO()
    pages[0].save(buf, "PDF", save_all=True, append_images=pages[1:])
    buf.seek(0)
    return jsonify({"ok": True, "pdf": base64.b64encode(buf.read()).decode()})

@app.route("/vaktkurs-diplom", methods=["POST"])
def lag_vaktkurs_diplom():
    avvist = krev_hemmelighet()
    if avvist:
        return avvist
    data = request.json
    navn = data.get("navn", "")
    dato = data.get("dato", "")
    poeng = data.get("poeng", "")
    maks = data.get("maks", "")

    img, draw = new_page()

    # Ramme rundt hele diplomet
    draw.rectangle([MARGIN - 30, 70, PAGE_W - MARGIN + 30, PAGE_H - 120], outline=DGREEN, width=4)
    draw.rectangle([MARGIN - 20, 80, PAGE_W - MARGIN + 20, PAGE_H - 130], outline=GREEN, width=2)

    def midtstill(tekst, font, y, farge):
        bbox = draw.textbbox((0, 0), tekst, font=font)
        x = (PAGE_W - (bbox[2] - bbox[0])) // 2
        draw.text((x, y), tekst, font=font, fill=farge)
        return y + (bbox[3] - bbox[1])

    y = 300
    y = midtstill("NORSJØ BYGDEUNGDOMSLAG", get_font(28), y, GREY) + 70
    y = midtstill("DIPLOM", get_font(90), y, DGREEN) + 50
    y = midtstill("Sertifisert vakt", get_font(46), y, GREEN) + 120

    y = midtstill("Dette bekrefter at", get_font_regular(26), y, INK) + 60
    y = midtstill(navn, get_font(56), y, DGREEN) + 80

    brodtekst = ("har gjennomført og bestått vaktkurset til Norsjø Bygdeungdomslag, "
                 "og er med det sertifisert til å ha vaktoppdrag på arrangementene våre.")
    body_font = get_font_regular(24)
    for linje in wrap_text(draw, brodtekst, body_font, PAGE_W - 2 * MARGIN - 120):
        y = midtstill(linje, body_font, y, INK) + 18
    y += 100

    if poeng != "" and maks != "":
        y = midtstill(f"Resultat på kunnskapsprøven: {poeng} av {maks} riktige", get_font(26), y, INK) + 80

    y = midtstill(f"Bestått {dato}", get_font_regular(24), y, GREY) + 150

    # Signaturlinje
    linje_bredde = 420
    x0 = (PAGE_W - linje_bredde) // 2
    draw.line([(x0, y), (x0 + linje_bredde, y)], fill=INK, width=2)
    y += 18
    midtstill("Norsjø Bygdeungdomslag", get_font_regular(22), y, GREY)

    draw_footer(draw, 1, 1, "Norsjø Bygdeungdomslag, diplom for sertifisert vakt")

    buf = io.BytesIO()
    img.save(buf, "PDF")
    buf.seek(0)
    return jsonify({"ok": True, "pdf": base64.b64encode(buf.read()).decode()})

@app.route("/hendelsesrapport", methods=["POST"])
def lag_hendelsesrapport():
    avvist = krev_hemmelighet()
    if avvist:
        return avvist
    data = request.json
    navn = data.get("navn", "")
    tittel = data.get("tittel", "")
    beskrivelse = data.get("beskrivelse", "")
    arrangement = data.get("arrangement", "")
    dato = data.get("dato", "")
    bilder_b64 = data.get("bilderB64", [])

    title_font = get_font(40)
    h2_font = get_font(24)
    label_font = get_font_regular(20)
    value_font = get_font(22)
    body_font = get_font_regular(21)

    pages = []
    img, draw = new_page()
    y = 70
    draw.text((MARGIN, y), "Norsjø Bygdeungdomslag", font=get_font(24), fill=GREY)
    y += 50
    draw.text((MARGIN, y), "Hendelsesrapport", font=title_font, fill=DGREEN)
    y += 74

    felt = [("Innsendt av", navn), ("Dato", dato), ("Arrangement", arrangement or "Ikke oppgitt")]
    for label, verdi in felt:
        draw.text((MARGIN, y), label.upper(), font=label_font, fill=GREY)
        draw.text((MARGIN + 260, y - 2), str(verdi), font=value_font, fill=INK)
        y += 38
    y += 20
    draw.line([(MARGIN, y), (PAGE_W - MARGIN, y)], fill=(220, 218, 205), width=2)
    y += 40

    draw.text((MARGIN, y), tittel, font=h2_font, fill=DGREEN)
    y += 46

    lines = wrap_text(draw, beskrivelse, body_font, PAGE_W - 2 * MARGIN)
    max_y = PAGE_H - 140
    for line in lines:
        if y > max_y:
            pages.append(img)
            img, draw = new_page()
            y = 80
        draw.text((MARGIN, y), line, font=body_font, fill=INK)
        y += 32
    pages.append(img)

    # Bilder, ett per side, tilpasset sideformat
    for b64 in bilder_b64:
        try:
            photo = Image.open(io.BytesIO(base64.b64decode(b64.split(",")[-1]))).convert("RGB")
        except Exception:
            continue
        pimg, pdraw = new_page()
        pdraw.text((MARGIN, 60), "Bilde til hendelsesrapport", font=label_font, fill=GREY)
        max_w = PAGE_W - 2 * MARGIN
        max_h = PAGE_H - 220
        ratio = min(max_w / photo.width, max_h / photo.height)
        new_size = (int(photo.width * ratio), int(photo.height * ratio))
        photo = photo.resize(new_size)
        px = (PAGE_W - new_size[0]) // 2
        py = 110 + (max_h - new_size[1]) // 2
        pimg.paste(photo, (px, py))
        pages.append(pimg)

    total = len(pages)
    for i, p in enumerate(pages):
        d = ImageDraw.Draw(p)
        draw_footer(d, i + 1, total, "Norsjø Bygdeungdomslag – Hendelsesrapport")

    buf = io.BytesIO()
    pages[0].save(buf, "PDF", save_all=True, append_images=pages[1:])
    buf.seek(0)
    return jsonify({"ok": True, "pdf": base64.b64encode(buf.read()).decode()})

@app.route("/billett", methods=["POST"])
def lag_billett():
    avvist = krev_hemmelighet()
    if avvist:
        return avvist
    data = request.json
    navn = data.get("navn", "")
    alder = str(data.get("alder", ""))
    arrangement = data.get("arrangement", "").upper()
    status = data.get("status", "")
    idag = data.get("idag", "")
    kode = data.get("kode", "")
    reg_id = data.get("regId", 0)
    ev_id = data.get("evId", 0)

    # Last inn template-bilder
    s1 = Image.open(io.BytesIO(base64.b64decode(SIDE1_B64))).convert("RGBA")
    s2 = Image.open(io.BytesIO(base64.b64decode(SIDE2_B64))).convert("RGBA")
    W, H = s1.size  # 1700 x 550

    krem = (240, 237, 216)
    dg = (74, 93, 36)

    bold = get_font(28)
    regular = get_font_regular(24)
    small = get_font_regular(20)

    # ── Side 1: Deltaker info ──
    draw1 = ImageDraw.Draw(s1)
    x = 1358
    draw1.text((x, 95), navn, font=bold, fill=krem)
    draw1.text((x, 162), alder + " år", font=bold, fill=krem)
    draw1.text((x, 229), status, font=bold, fill=krem)
    draw1.text((x, 295), idag, font=regular, fill=krem)

    # ── Side 2: Billett med QR ──
    draw2 = ImageDraw.Draw(s2)

    # Arrangementnavn
    arr_font = get_font(50)
    bbox = draw2.textbbox((0, 0), arrangement, font=arr_font)
    arr_w = bbox[2] - bbox[0]
    midX = 800  # Sentrum av grønt felt (mellom sprellemannen og hvit stubb)
    draw2.text((midX - arr_w // 2, 210), arrangement, font=arr_font, fill=krem)

    # QR-kode
    qr_data = json.dumps({"id": reg_id, "kode": kode, "ev": ev_id})
    qr = qrcode.QRCode(version=2, box_size=6, border=2,
        error_correction=qrcode.constants.ERROR_CORRECT_M)
    qr.add_data(qr_data)
    qr.make(fit=True)
    qr_img = qr.make_image(fill_color="black", back_color="white").convert("RGBA")
    qr_size = 210

    # Hvit bakgrunn over QR-felt
    draw2.rectangle([1342, 79, 1342 + 238, 79 + 285], fill="white")

    # QR sentrert
    qr_resized = qr_img.resize((qr_size, qr_size))
    qr_x = 1342 + (238 - qr_size) // 2
    s2.paste(qr_resized, (qr_x, 89), qr_resized)

    # Kode under QR
    bbox_k = draw2.textbbox((0, 0), kode, font=small)
    kode_w = bbox_k[2] - bbox_k[0]
    draw2.rectangle([1342, 320, 1342 + 238, 360], fill="white")
    draw2.text((1342 + (238 - kode_w) // 2, 325), kode, font=small, fill=dg)

    # Slå sammen til ett bilde
    gap = 20
    total = Image.new("RGB", (W, H * 2 + gap), (247, 245, 238))
    total.paste(s1.convert("RGB"), (0, 0))
    total.paste(s2.convert("RGB"), (0, H + gap))

    buf = io.BytesIO()
    total.save(buf, "PNG", optimize=True)
    buf.seek(0)
    png_b64 = base64.b64encode(buf.read()).decode()

    return jsonify({"ok": True, "png": png_b64})

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port)
